# idea: fine high-frequency Gabor ladder with HMAX C1 max-pooling + colour-form conv hierarchy
"""
Untrained HMAX-style vision model. S1: Gabor quadrature energy over a FINE high-frequency ladder
(lambda 2-9 px, 8 orientations) on luminance -- NSD's fine local-contrast signal. C1: local MAX
pooling of S1 energy for position/scale tolerance (HMAX complex cells). Colour-opponent energy too.
C1 luminance+colour maps feed four random He conv layers (ReLU+maxpool) for ventral selectivity,
plus a bilinear co-occurrence block. Readout = per-block L2-normalised spatial mean/std pools.
Per-sample, deterministic, never trained.
"""
import math
import torch
import torch.nn.functional as F

SEED = 0
GAMMA = 0.4    # energy compression exponent
GAMMA_APP = 0.6   # appearance compression (decoupled; 0.6 optimal, less heavy-tailed than energy)
GAMMA_COL = 0.40  # colour-energy compression (re-tuned 0.40)
GAMMA_LUM = 0.21 # fine-luminance compression (re-tuned 0.21; strongly lifts ventral)
GAMMA_SCAT = 0.55 # scattering compression (0.55; energy-of-energy needs less)
GAMMA_H0 = 0.50   # conv-input compression (re-tuned 0.50, stronger-compression regime)
GAMMA_CI = 0.4    # contrast-invariant energy compression (flat ~0.4)
CPOOL = 2         # HMAX C1 max-pool (2 best: finer spatial helps V1)
CPOOL_CI = 5      # coarse C1 pool for contrast-invariant branch (5 optimal)


def _gabor_bank(K, lambdas, n_orient, sigma_ratio=0.5, gamma=0.5):
    half = K // 2
    ys, xs = torch.meshgrid(torch.arange(-half, half + 1.0),
                            torch.arange(-half, half + 1.0), indexing="ij")
    ev, od = [], []
    for lam in lambdas:
        sigma = sigma_ratio * lam
        for o in range(n_orient):
            th = o * math.pi / n_orient
            xr = xs * math.cos(th) + ys * math.sin(th)
            yr = -xs * math.sin(th) + ys * math.cos(th)
            env = torch.exp(-(xr ** 2 + (gamma ** 2) * yr ** 2) / (2 * sigma ** 2))
            e = env * torch.cos(2 * math.pi * xr / lam)
            o_ = env * torch.sin(2 * math.pi * xr / lam)
            e = e - e.mean()
            e = e / (e.norm() + 1e-8)
            o_ = o_ / (o_.norm() + 1e-8)
            ev.append(e); od.append(o_)
    return torch.stack(ev).unsqueeze(1), torch.stack(od).unsqueeze(1)


def _he_conv(out_ch, in_ch, k, seed):
    g = torch.Generator().manual_seed(seed)
    w = torch.randn(out_ch, in_ch, k, k, generator=g)
    w *= (2.0 / (in_ch * k * k)) ** 0.5
    return w


def _ln(f):
    # per-sample RMS balance: scale each branch to ~unit per-feature RMS so the ridge weights
    # branches by signal, not by branch size/scale (block-L2 would shrink large branches).
    rms = f.pow(2).mean(dim=1, keepdim=True).sqrt()
    return f / (rms + 0.05)


def _meanstd(c, m, s):
    N = c.shape[0]
    mean = F.adaptive_avg_pool2d(c, m).reshape(N, -1)
    ex = F.adaptive_avg_pool2d(c, s)
    ex2 = F.adaptive_avg_pool2d(c * c, s)
    std = (ex2 - ex * ex).clamp_min(0).sqrt().reshape(N, -1)
    return torch.cat([_ln(mean), _ln(std)], dim=1)


def _msm(c, m, s):
    """mean(m x m) + std(s x s) + MAX(s x s) pools (HMAX-style presence), each RMS-balanced."""
    N = c.shape[0]
    mean = F.adaptive_avg_pool2d(c, m).reshape(N, -1)
    ex = F.adaptive_avg_pool2d(c, s)
    ex2 = F.adaptive_avg_pool2d(c * c, s)
    std = (ex2 - ex * ex).clamp_min(0).sqrt().reshape(N, -1)
    mx = F.adaptive_max_pool2d(c, s).reshape(N, -1)
    return torch.cat([_ln(mean), _ln(std), _ln(mx)], dim=1)


class Model:
    name = "shape-colour-champion-c2-abs"
    idea = "use abs (phase-invariant) instead of ReLU at the mid-level c2 conv, keeping both halves of each random projection so the part-Gram sees richer mid-level features"
    description = (
        "Untrained, per-sample. The champion ao8f0 (2x-resolution deep pathway) with the c2 conv "
        "nonlinearity changed from ReLU to ABS (magnitude), matching what c3 already does. c2 then keeps "
        "the full magnitude of both the positive and negative halves of each random mid-level projection "
        "instead of zeroing the negatives. Everything else unchanged.")
    insight = (
        "c3 uses abs (a complex-cell, phase-invariant nonlinearity that doubles usable info vs ReLU) and it "
        "won there; c2 still uses ReLU, discarding half of each mid-level projection. The c2 part-Gram is "
        "my key high-level feature, so giving it richer (full-magnitude) c2 inputs -- now at the finer "
        "32x32 resolution -- should sharpen the part co-occurrence it reads. If ventral/FFA rise, the mid "
        "level also wants phase invariance and I keep it; if it dips, ReLU's sparsity/rectification was "
        "load-bearing for the part structure and I revert to ao8f0.")

    def __init__(self):
        self.E1, self.O1 = _gabor_bank(21, [2.0, 3.0, 4.0, 6.0, 9.0], 8)  # 40
        self.Ec, self.Oc = _gabor_bank(21, [3.0, 6.0, 10.0], 4)           # 12 filters per colour chan
        self.E2, self.O2 = _gabor_bank(13, [2.0, 4.0], 4)                # 8 second-layer scattering wavelets
        self.W2 = _he_conv(256, 122, 3, SEED + 2)   # 122 = 40 c1 + 72 c1c + 10 app (incl 3 raw absolute)
        self.W3 = _he_conv(512, 256, 3, SEED + 3)
        gpc2 = torch.Generator().manual_seed(SEED + 7)
        self.Pc2m = torch.randn(256, 130, generator=gpc2) / (256.0 ** 0.5)   # projection for the tight foveal c2 MEAN
        self.Pc2s = torch.randn(256, 70, generator=gpc2) / (256.0 ** 0.5)    # projection for the broad foveal c2 STD
        gpc3 = torch.Generator().manual_seed(SEED + 8)
        self.Pstd = torch.randn(512, 256, generator=gpc3) / (512.0 ** 0.5)   # projection for the deep foveal STD
        self.Psym = torch.randn(512, 256, generator=gpc3) / (512.0 ** 0.5)   # projection for the deep foveal L-R SYMMETRY
        gpg = torch.Generator().manual_seed(SEED + 11)
        self.Pc2g = torch.randn(256, 16, generator=gpg) / (256.0 ** 0.5)     # compress c2 to 16 for the compact part-Gram
        self.n_params = sum(t.numel() for t in
                            (self.E1, self.O1, self.Ec, self.Oc, self.E2, self.O2, self.W2, self.W3,
                             self.Pc2m, self.Pc2s, self.Pstd, self.Psym, self.Pc2g))
        self._dev = None

    def _to(self, dev):
        if self._dev != dev:
            for a in ("E1", "O1", "Ec", "Oc", "E2", "O2", "W2", "W3", "Pc2m", "Pc2s", "Pstd", "Psym", "Pc2g"):
                setattr(self, a, getattr(self, a).to(dev))
            self._dev = dev

    def _energy(self, x, E, O, stride=1, groups=1):
        pad = E.shape[-1] // 2
        ev = F.conv2d(x, E, stride=stride, padding=pad, groups=groups)
        od = F.conv2d(x, O, stride=stride, padding=pad, groups=groups)
        return torch.sqrt(ev * ev + od * od + 1e-6)

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X)
        # Sub-chunk the forward pass to keep peak GPU memory low (shared GPU).
        bs = 16
        if X.shape[0] > bs:
            return torch.cat([self._forward_one(X[i:i + bs]) for i in range(0, X.shape[0], bs)], 0)
        return self._forward_one(X)

    @torch.no_grad()
    def _forward_one(self, X):
        dev = X.device
        self._to(dev)
        N = X.shape[0]
        side = round((X.shape[1] / 3) ** 0.5)
        x = X.reshape(N, side, side, 3).permute(0, 3, 1, 2).float()
        xraw = x                                            # RAW pixels BEFORE per-image normalization
        mu = x.mean(dim=(1, 2, 3), keepdim=True)
        sd = x.std(dim=(1, 2, 3), keepdim=True).clamp_min(1e-6)
        x = (x - mu) / sd
        r, g, b = x[:, 0:1], x[:, 1:2], x[:, 2:3]
        lum = (r + g + b) / 3.0
        # ABSOLUTE (raw, pre-normalization) brightness/colour layout -- the per-image normalization
        # above removes the absolute level, but NSD voxels encode it (dark=indoor, bright=outdoor,
        # warm=sunset). Read raw RGB at a coarse colour-layout grid + raw luminance at a finer grid.
        rawlum = xraw.mean(dim=1, keepdim=True)             # (N,1,H,W) absolute luminance
        rr, gg, bb = xraw[:, 0:1], xraw[:, 1:2], xraw[:, 2:3]
        rawopp = torch.cat([rr - gg, (rr + gg) / 2 - bb], dim=1)   # absolute opponent colour (warm/cool)
        fraw = torch.cat([_ln(F.adaptive_avg_pool2d(xraw, 6).reshape(N, -1)),       # 3*36 = 108
                          _ln(F.adaptive_avg_pool2d(rawlum, 9).reshape(N, -1)),     # 81
                          _ln(F.adaptive_avg_pool2d(rawopp, 6).reshape(N, -1)),     # 2*36 = 72 absolute opponent layout
                          # absolute colour EXTREMES per region: brightest/darkest colour (sky/ground/
                          # object cues) -- the raw analogue of the max/min that won on the normalized appearance.
                          _ln(F.adaptive_max_pool2d(xraw, 4).reshape(N, -1)),       # 3*16 = 48 bright
                          _ln((-F.adaptive_max_pool2d(-xraw, 4)).reshape(N, -1)),   # 3*16 = 48 dark
                          # absolute LOCAL contrast/texture: std of raw RGB / luminance per region
                          # (the energy captures only contrast-NORMALISED structure; absolute local
                          # variation is a distinct material/texture cue).
                          _ln((F.adaptive_avg_pool2d(xraw * xraw, 4)
                               - F.adaptive_avg_pool2d(xraw, 4) ** 2).clamp_min(0).sqrt().reshape(N, -1)),  # 48
                          _ln((F.adaptive_avg_pool2d(rawlum * rawlum, 5)
                               - F.adaptive_avg_pool2d(rawlum, 5) ** 2).clamp_min(0).sqrt().reshape(N, -1)),  # 25
                          _ln(xraw.amax(dim=(2, 3))), _ln(xraw.amin(dim=(2, 3)))],  # 3+3 global extremes
                         dim=1)                             # +73 local-std = 364
        # CATEGORICAL HUE composition ("what colour WHERE"): the ventral colour areas (V4/VO) encode
        # HUE largely separably from chroma, but every existing colour branch is a LINEAR opponent
        # readout -- a linear ridge cannot recover a hue HISTOGRAM from opponent means. Soft-bin the
        # raw opponent ANGLE into 8 overlapping hue channels, each GATED by chroma (saturated pixels
        # vote, grey pixels don't), and read the spatial layout + global histogram. A nonlinear, hue-
        # selective, absolute-colour signal orthogonal to the opponent-energy and opponent-mean branches.
        rgc, byc = rr - gg, (rr + gg) / 2.0 - bb
        hue = torch.atan2(byc, rgc)                          # (N,1,H,W)
        chroma = torch.sqrt(rgc * rgc + byc * byc + 1e-6)
        # per-image LIGHTNESS gate (scale-robust): split each hue into a BRIGHT and a DARK band so the
        # branch encodes full colour APPEARANCE (dark-green foliage vs light-green, navy vs sky) -- the
        # 3rd colour dimension (hue x chroma x lightness) the ventral colour areas (V4/VO) represent.
        rmin = rawlum.amin(dim=(2, 3), keepdim=True)
        rmax = rawlum.amax(dim=(2, 3), keepdim=True)
        L = (rawlum - rmin) / (rmax - rmin + 1e-6)           # (N,1,H,W) in [0,1]
        pure_bins, hbins = [], []
        for k in range(8):
            ck = -math.pi + 2.0 * math.pi * k / 8.0
            base = chroma * torch.cos(hue - ck).clamp_min(0).pow(3)   # narrow hue-selective, chroma-gated
            pure_bins.append(base)
            hbins.append(base * L)                           # bright band
            hbins.append(base * (1.0 - L))                  # dark band
        huemap = torch.cat(hbins, dim=1)                    # (N,16,H,W) 8 hue x 2 lightness
        puremap = torch.cat(pure_bins, dim=1)               # (N,8,H,W) pure hue
        fhue = torch.cat([_ln(F.adaptive_avg_pool2d(huemap, 4).reshape(N, -1)),   # 16*16 = 256 hue x light layout
                          _ln(puremap.mean(dim=(2, 3)))], dim=1)                   # +8 global pure-hue hist = 264
        # CHROMATIC FORM (hue x orientation): apply the 2nd Gabor bank to each of the 8 pure-hue maps to
        # get the ORIENTED structure WITHIN each colour category -- a vertical red edge, a horizontal
        # green texture -- i.e. colour bound to form. Distinct from the luminance edges and from the
        # opponent-energy (only 2 chromatic axes): here every hue category carries its own oriented
        # contour/texture signature, a V4-style colour-form conjunction. Read global mean+std of energy.
        pm = F.adaptive_avg_pool2d(puremap, 32)             # (N,8,32,32) coarse colour maps
        E2r8 = self.E2.repeat(8, 1, 1, 1); O2r8 = self.O2.repeat(8, 1, 1, 1)
        p2h = self.E2.shape[-1] // 2
        ehf = torch.sqrt(F.conv2d(pm, E2r8, padding=p2h, groups=8) ** 2
                         + F.conv2d(pm, O2r8, padding=p2h, groups=8) ** 2 + 1e-6).pow(GAMMA_SCAT)   # (N,64,32,32)
        fhform = torch.cat([_ln(F.adaptive_avg_pool2d(ehf, 2).reshape(N, -1)),   # 64*4 = 256 chromatic-form 2x2 layout (WHERE colored structure is)
                            _ln(ehf.std(dim=(2, 3)))], dim=1)   # +64 = 320 chromatic form
        # ACHROMATIC LUMINANCE-TONE histogram: the chroma-gated hue branch is BLIND to greys, but
        # achromatic tone composition (shadows, sky/concrete gradients, white/black objects) is a strong
        # scene/material cue (PPA, backgrounds). Soft-bin the per-image lightness L into 6 overlapping
        # tone bands (a nonlinear recoding of the luminance DISTRIBUTION the linear mean/std cannot
        # express -- high-key vs low-key, bimodal contrast) and read a 3x3 layout + global histogram.
        tbins = []
        for k in range(6):
            ck = k / 5.0
            tbins.append((1.0 - (L - ck).abs() * 5.0).clamp_min(0))   # triangular tone band centred at ck
        tonemap = torch.cat(tbins, dim=1)                   # (N,6,H,W)
        ftone = torch.cat([_ln(F.adaptive_avg_pool2d(tonemap, 3).reshape(N, -1)),   # 6*9 = 54 tone layout
                           _ln(tonemap.mean(dim=(2, 3)))], dim=1)                    # +6 global tone hist = 60

        # 0th-order appearance: signed low-pass luminance + opponent colour + saturation per region
        # (absolute brightness/colour the energy/edge features discard). Mean = dominant local
        # colour/brightness; std = within-region colour-texture variation (material cue for ventral).
        sat = torch.sqrt((r - g) ** 2 + ((r + g) / 2 - b) ** 2 + 1e-6)
        appmaps = torch.cat([lum, r - g, (r + g) / 2 - b, sat], dim=1)   # (N,4,128,128)
        # sign-preserving compression of the appearance (the last uncompressed branch): tame its tail
        # too while keeping the sign of opponent-colour/brightness -- same conditioning that won elsewhere.
        appmaps = appmaps.sign() * appmaps.abs().pow(GAMMA_APP)
        amean = F.adaptive_avg_pool2d(appmaps, 9)
        astd = (F.adaptive_avg_pool2d(appmaps * appmaps, 6)
                - F.adaptive_avg_pool2d(appmaps, 6) ** 2).clamp_min(0).sqrt()
        # also a signed MAX/min layout: the most-positive and most-negative region per opponent channel
        # (most-red vs most-green, brightest vs darkest) -- salient absolute-colour extremes for ventral.
        amax = F.adaptive_max_pool2d(appmaps, 4)
        amin = -F.adaptive_max_pool2d(-appmaps, 4)
        # GLOBAL scene statistics per channel: whole-image signed extremes (dominant object colour) +
        # std/skew/kurtosis of the colour distribution -- natural-image summary cues that drive scene
        # (PPA) responses. These are nonlinear (not recoverable from the spatial means), per-image.
        flat = appmaps.reshape(N, appmaps.shape[1], -1)
        gmax = flat.amax(dim=2)
        gmin = flat.amin(dim=2)
        gmu = flat.mean(dim=2, keepdim=True)
        gsd = flat.std(dim=2)
        cen = flat - gmu
        gskew = (cen.pow(3).mean(dim=2)) / (gsd.pow(3) + 1e-6)
        gkurt = (cen.pow(4).mean(dim=2)) / (gsd.pow(4) + 1e-6)
        gstats = _ln(torch.cat([gmax, gmin, gsd, gskew, gkurt], dim=1))   # 4*5 = 20
        s0 = torch.cat([amean.reshape(N, -1), astd.reshape(N, -1),
                        amax.reshape(N, -1), amin.reshape(N, -1)], dim=1)  # 4*81+4*36+4*16+4*16 = 596
        s1 = self._energy(lum, self.E1, self.O1, stride=1)          # (N,40,128,128) full res
        c1 = F.max_pool2d(s1, CPOOL)                                # HMAX C1 (max over CPOOLxCPOOL); invariance knob
        # SCATTERING layer 2 (texture pathway, funded by the redundant mid-conv spatial detail): apply
        # a second Gabor bank to the finest C1 energy channels (lambda 2/3, 16ch), take the energy of
        # the result -> oriented MODULATIONS of edge-energy = texture (how busy/regular each region is),
        # a category-diagnostic ventral/PPA cue. Read at a 2x2 layout grid + global std + max.
        hf = c1[:, :16]
        E2r = self.E2.repeat(16, 1, 1, 1); O2r = self.O2.repeat(16, 1, 1, 1)
        p2 = self.E2.shape[-1] // 2
        s2 = torch.sqrt(F.conv2d(hf, E2r, padding=p2, groups=16) ** 2
                        + F.conv2d(hf, O2r, padding=p2, groups=16) ** 2 + 1e-6).pow(GAMMA_SCAT)   # (N,128,32,32)
        fscat = torch.cat([_ln(F.adaptive_avg_pool2d(s2, 3).reshape(N, -1)),   # 128*9 = 1152 finer texture layout
                           _ln(s2.std(dim=(2, 3)))], dim=1)   # +128 -> 1280 (texture)

        col = torch.cat([r, g, b, r - g, (r + g) / 2 - b,
                         torch.sqrt((r - g) ** 2 + ((r + g) / 2 - b) ** 2 + 1e-6)], dim=1)  # 6 chans
        Ec = self.Ec.repeat(6, 1, 1, 1); Oc = self.Oc.repeat(6, 1, 1, 1)
        ec = self._energy(col, Ec, Oc, stride=2, groups=6)         # (N,72,64,64) full-colour edges
        c1c = F.max_pool2d(ec, 2)                                   # (N,72,32,32)
        # CHROMATIC TEXTURE (colour scattering): 2nd Gabor bank on the opponent-colour oriented energy
        # = energy-of-colour-energy = coloured texture (foliage/skin/fabric/sky), a ventral MATERIAL cue
        # (lifted ventral/hV4/V3/FFA in isolation). Global mean. Funded by one luminance-autocorr lag.
        cco = c1c[:, 36:60]                                          # (N,24,32,32) opponent-colour (r-g, y-b) energies
        E2c = self.E2[:3].repeat(24, 1, 1, 1); O2c = self.O2[:3].repeat(24, 1, 1, 1)   # 3 finest orientations
        p2c = self.E2.shape[-1] // 2
        cscat = torch.sqrt(F.conv2d(cco, E2c, padding=p2c, groups=24) ** 2
                           + F.conv2d(cco, O2c, padding=p2c, groups=24) ** 2 + 1e-6).pow(GAMMA_SCAT)   # (N,72,32,32)
        fcscat = _ln(cscat.mean(dim=(2, 3)))                        # 24*3 = 72 chromatic texture

        # absolute appearance maps at conv resolution (signed lum/colour/saturation) -> let the
        # conv pathway build colour-appearance-form conjunctions, not just edge-energy combinations.
        app = torch.cat([lum, r - g, (r + g) / 2 - b, sat, r, g, b], dim=1)   # (N,7,128,128)
        app = F.adaptive_avg_pool2d(app, 64)                         # (N,7,64,64) -- 2x deep-pathway resolution
        # also feed RAW ABSOLUTE appearance into the conv pathway: absolute luminance + opponent colour
        # so the convs can build ABSOLUTE-colour/brightness-conditioned conjunctions (raw appearance is
        # my highest-value readout signal; let the ventral-engine convs use it, not just normalised app).
        app = torch.cat([app, F.adaptive_avg_pool2d(rawlum, 64),
                         F.adaptive_avg_pool2d(rawopp, 64)], dim=1)  # +1 rawlum +2 rawopp -> (N,10,64,64)
        # Build the deep-pathway input on COMPRESSED energy too (same amplitude**0.5 nonlinearity
        # that won the readout): the convs then see well-conditioned, tamed-tail inputs instead of a
        # few high-contrast edges dominating -- better mid/ventral conjunctions. (app stays signed.)
        # HIGHER-RESOLUTION deep pathway: build h0 at 64x64 (was 32x32) so the random convs produce FINER
        # high-level features -> c2 at 32x32, c3 at 16x16. Object PARTS (FFA/VWFA) get finer spatial
        # support; all deep reads auto-adapt to the layer sizes. c1 is already 64x64 (real); c1c is
        # upsampled from 32x32; app is pooled to 64x64 (real).
        c1_64 = c1 if c1.shape[-1] == 64 else F.adaptive_max_pool2d(c1, 64)
        c1c_64 = F.interpolate(c1c, size=(64, 64), mode="bilinear", align_corners=False)
        h0 = torch.cat([c1_64.pow(GAMMA_H0), c1c_64.pow(GAMMA_H0), app], dim=1)      # (N,119,64,64)
        # divisive normalisation for the deep pathway ONLY (contrast gain control -> cleaner mid/high
        # features); the early readout keeps RAW energy so V1 retains the contrast it encodes.
        _unused = h0
        # The deep input is ALREADY compressed (heavy tail tamed), so the old divisive normalisation
        # (added for raw energy) may now over-normalise away useful contrast -- feed compressed h0 direct.
        c2 = F.max_pool2d(F.conv2d(h0, self.W2, padding=1).abs(), 2)   # (N,256,32,32) abs (phase-invariant): keep both halves of each mid-level projection
        # ABSOLUTE VALUE (not ReLU) at the deep conv: a phase-invariant complex-cell nonlinearity that
        # keeps BOTH the positive and negative halves of each random projection as feature magnitudes,
        # doubling the usable information vs ReLU (which zeroes the negative half) -- richer ventral.
        c3 = F.max_pool2d(F.conv2d(c2, self.W3, padding=1).abs(), 2)    # (N,512,16,16) -- finer (was 8x8)

        f0 = _ln(s0)
        # COMPRESS the heavy-tailed raw energy (amplitude**0.5) before the readout pools: a
        # compressive nonlinearity (like cortical contrast response) tames the high-contrast tail so
        # the energy features are far more linearly decodable by the ridge -> higher train+test.
        f1 = _meanstd(c1.pow(GAMMA_LUM), 9, 2)   # fine lum: 40*81 + 40*4 = 3400 (std grid 3x3->2x2 to fund the part-Gram; mean 9x9 kept)
        # contrast-invariant energy: divisively-normalise C1 by local total energy, read coarsely.
        # Use a COARSER C1 max-pool here (more position/phase invariance) -- this branch serves the
        # higher areas (hV4/ventral), which preferred a coarse pool, while f1 keeps the fine pool for V1.
        c1co = F.max_pool2d(s1, CPOOL_CI)
        ct = c1co.sum(dim=1, keepdim=True)
        cl = F.avg_pool2d(ct, 5, stride=1, padding=2)
        c1n = c1co / (cl.mean(dim=(2, 3), keepdim=True) + cl + 1e-3)
        # CONTRAST-INVARIANT Gram: cross-orientation co-occurrence of the divisively-normalised energy
        # (texture STRUCTURE independent of contrast) -> cleaner texture signature for higher areas.
        cgn = c1n[:, :24].reshape(N, 24, -1)
        cgn = cgn / (cgn.norm(dim=2, keepdim=True) + 1e-6)
        gramn = torch.bmm(cgn, cgn.transpose(1, 2))
        fgramn = _ln(gramn[:, torch.triu_indices(24, 24, offset=1, device=gramn.device)[0],
                           torch.triu_indices(24, 24, offset=1, device=gramn.device)[1]])   # 276 contrast-inv texture
        fc = _msm(c1c.pow(GAMMA_COL), 3, 2)  # full-colour: 72*9 + 72*4 + 72*4 = 1224 (compressed, 3x3)
        # CROSS-ORIENTATION GRAM (Freeman-Simoncelli V2/V4 texture): correlation between the finest 24
        # oriented-energy channels over space -> which orientations/scales CO-OCCUR (corners/crosses vs
        # lines, texture regularity). Channel-normalised => correlation, per-image, read globally.
        cg = c1[:, :24].reshape(N, 24, -1)
        cg = cg / (cg.norm(dim=2, keepdim=True) + 1e-6)
        gram = torch.bmm(cg, cg.transpose(1, 2))           # (N,24,24)
        iu = torch.triu_indices(24, 24, offset=1, device=gram.device)
        fgram = _ln(gram[:, iu[0], iu[1]])                 # 24*23/2 = 276 cross-orientation correlations
        # SPATIAL-PYRAMID texture Gram (position-tagged texture = "what texture, WHERE" -- exactly what
        # FFA/PPA encode): cross-orientation co-occurrence of the 12 finest channels in each of a 3x3
        # grid of overlapping-free cells -> object/scene texture localised. Channel-normalised correlation.
        ch12 = c1[:, :12]
        H12 = ch12.shape[-1]
        iu2 = torch.triu_indices(12, 12, offset=1, device=ch12.device)
        sg = []
        for i in range(3):
            for j in range(3):
                a0, a1 = (i * H12) // 3, ((i + 1) * H12) // 3
                b0, b1 = (j * H12) // 3, ((j + 1) * H12) // 3
                blk = ch12[:, :, a0:a1, b0:b1].reshape(N, 12, -1)
                blk = blk / (blk.norm(dim=2, keepdim=True) + 1e-6)
                g2 = torch.bmm(blk, blk.transpose(1, 2))
                sg.append(g2[:, iu2[0], iu2[1]])
        fsgram = _ln(torch.cat(sg, dim=1))                 # 9 * 66 = 594 position-tagged texture
        # ENERGY SPATIAL AUTOCORRELATION (Portilla-Simoncelli texture periodicity/regularity): each C1
        # channel's correlation with itself shifted a few px -> periodic/regular vs random texture, a
        # material/texture cue orthogonal to the cross-channel Gram (zero-lag). Per-channel, global.
        cn = c1 - c1.mean(dim=(2, 3), keepdim=True)
        acvar = (cn * cn).mean(dim=(2, 3)) + 1e-6
        acs = []
        for dy, dx in [(0, 2), (2, 0), (2, 2)]:
            sh = torch.roll(cn, shifts=(dy, dx), dims=(2, 3))
            acs.append((cn * sh).mean(dim=(2, 3)) / acvar)   # (N,40)
        fac = _ln(torch.cat(acs, dim=1))                   # 3 * 40 = 120 luminance autocorr (restored; f2 funds it)
        # CORNER / JUNCTION / CURVATURE statistic: cross-orientation correlation at a spatial OFFSET ->
        # which orientations CO-OCCUR DISPLACED = corners (perpendicular meet), T-junctions, curves,
        # collinear continuation. An explicit mid-level SHAPE statistic (V2/V4) -- the generalizing
        # STATISTIC form of curvature. Now MULTI-SCALE at CONSTANT budget: fine (lambda2, small offsets =
        # fine contour corners) + coarse (lambda3, larger offsets = object-PART geometry), 2 offsets each,
        # so the higher ventral areas get coarse shape without ADDING dims (which dilutes the readout).
        HW = cn.shape[2] * cn.shape[3]
        cjs = []
        for ch0, offs in ((0, [(0, 2), (2, 0), (2, 2)]), (8, [(0, 3), (3, 0)]), (24, [(0, 6)])):
            band = cn[:, ch0:ch0 + 8]
            bs = band.pow(2).mean(dim=(2, 3)).sqrt() + 1e-6
            for dy, dx in offs:
                rolled = torch.roll(band, shifts=(dy, dx), dims=(2, 3))
                cross = torch.bmm(band.reshape(N, 8, -1), rolled.reshape(N, 8, -1).transpose(1, 2)) / HW
                cross = cross / (bs.unsqueeze(2) * bs.unsqueeze(1) + 1e-6)
                cjs.append(cross.reshape(N, -1))           # 64
        fcj = _ln(torch.cat(cjs, dim=1))                   # 6 * 64 = 384 corner/junction across 3 scales (lambda2/3/4)
        # FOVEAL (center-weighted) pool of the deep high-level features: NSD/COCO images place the object
        # of interest centrally, and ventral object/face areas (FFA/VWFA/ventral) read the FOVEATED object,
        # not the full field. Replace the deep conv's GLOBAL mean with a center-Gaussian-weighted mean so
        # the readout sees the CENTRAL object's high-level features; the global MAX (f3max) still gives the
        # translation-invariant presence. Zero width cost vs the global mean.
        Hc = c3.shape[-1]
        yy, xx = torch.meshgrid(torch.arange(Hc, device=c3.device, dtype=c3.dtype),
                                torch.arange(Hc, device=c3.device, dtype=c3.dtype), indexing="ij")
        ctr = (Hc - 1) / 2.0
        r2 = (yy - ctr) ** 2 + (xx - ctr) ** 2
        fov = torch.exp(-r2 / (2.0 * (Hc * 0.07) ** 2)); fov = fov / fov.sum()
        fovs = torch.exp(-r2 / (2.0 * (Hc * 0.15) ** 2)); fovs = fovs / fovs.sum()
        fov_mean = (c3 * fov).sum(dim=(2, 3))                       # (N,512) tight foveal high-level mean
        # The deep central-object read combines TWO complementary spread signals at constant width by
        # projecting each to 256: the foveal STD (feature spread, helps ventral/FFA) and the foveal L-R
        # SYMMETRY (each c3 channel times its left-right mirror, central-pooled; a bilateral-symmetry
        # Gestalt cue that helps the early stream and generalises far better -- lower train/test gap).
        fov_m2 = (c3 * fovs).sum(dim=(2, 3))
        fov_std = ((c3 * c3 * fovs).sum(dim=(2, 3)) - fov_m2 ** 2).clamp_min(0).sqrt()   # (N,512) foveal feature spread
        c3f = torch.flip(c3, dims=[3])
        fov_sym = (c3 * c3f * fovs).sum(dim=(2, 3))                 # (N,512) foveal L-R symmetry energy
        f3 = torch.cat([_ln(fov_mean), _ln(fov_std @ self.Pstd), _ln(fov_sym @ self.Psym)], dim=1)   # 512 + 256 + 256 = 1024
        f3max = _ln(c3.amax(dim=(2, 3)))   # deep-conv GLOBAL MAX: translation-invariant feature presence (kept global -- central-crop max regressed)
        # FOVEAL MID-LEVEL read: the same central-object principle applied to the MID conv layer (c2,
        # 256ch 16x16) -- a tight center-Gaussian mean gives mid-level object-part features of the centred
        # object, one layer shallower than c3 (more parts/texture, less abstract). Funded by dropping the
        # low-value achromatic tone histogram (ftone).
        Hc2 = c2.shape[-1]
        yy2, xx2 = torch.meshgrid(torch.arange(Hc2, device=c2.device, dtype=c2.dtype),
                                  torch.arange(Hc2, device=c2.device, dtype=c2.dtype), indexing="ij")
        ctr2 = (Hc2 - 1) / 2.0
        r2c2 = (yy2 - ctr2) ** 2 + (xx2 - ctr2) ** 2
        fov2 = torch.exp(-r2c2 / (2.0 * (Hc2 * 0.025) ** 2)); fov2 = fov2 / fov2.sum()      # tight (central-point) MEAN
        fov2s = torch.exp(-r2c2 / (2.0 * (Hc2 * 0.15) ** 2)); fov2s = fov2s / fov2s.sum()   # broad foveal STD (needs a region)
        c2m = (c2 * fov2).sum(dim=(2, 3))
        c2m2 = (c2 * fov2s).sum(dim=(2, 3))
        c2std = ((c2 * c2 * fov2s).sum(dim=(2, 3)) - c2m2 ** 2).clamp_min(0).sqrt()
        fc2 = torch.cat([_ln(c2m @ self.Pc2m), _ln(c2std @ self.Pc2s)], dim=1)   # 130 tight mid mean + 70 broad mid std = 200
        # OBJECT GEOMETRY scalars: from the high-level saliency map (per-channel-mean of c3 / c2) compute
        # the centre-of-mass (where the salient object is) and the spread (how big / spatially extended it
        # is) -- explicit spatial coordinates that scene (PPA) and object (FFA/VWFA) areas can read. A
        # genuinely new, energy-orthogonal cue; kept raw (coords in [-1,1]) rather than RMS-balanced.
        geoms = []
        for feat in (c3, c2):
            sal = feat.mean(dim=1).clamp_min(0)                    # (N,h,w) saliency
            hh = sal.shape[-1]
            p = sal / (sal.sum(dim=(1, 2), keepdim=True) + 1e-6)
            gy, gx = torch.meshgrid(torch.linspace(-1, 1, hh, device=sal.device, dtype=sal.dtype),
                                    torch.linspace(-1, 1, hh, device=sal.device, dtype=sal.dtype), indexing="ij")
            cx = (p * gx).sum(dim=(1, 2)); cy = (p * gy).sum(dim=(1, 2))
            vx = (p * (gx - cx[:, None, None]) ** 2).sum(dim=(1, 2)).sqrt()
            vy = (p * (gy - cy[:, None, None]) ** 2).sum(dim=(1, 2)).sqrt()
            geoms.append(torch.stack([cx, cy, vx, vy], dim=1))     # (N,4)
        fgeom = torch.cat(geoms, dim=1)                            # 8 object-geometry scalars (c3 + c2)
        # COMPACT MID-LEVEL PART CO-OCCURRENCE (c2 part-Gram), kept alongside the FULL deep read: project
        # c2 to 16 channels, foveal-weight (central object), channel-normalize over space, take the
        # correlation upper-triangle (120 dims). The first signal to lift the high-level ROIs; funded NOT
        # by the deep foveal-STD (worth ~0.0004) but by the secondary f1 V1 STD grid (3x3->2x2), so the
        # valuable deep read survives and the part-Gram gain is no longer offset.
        c2g = torch.einsum("ncxy,ck->nkxy", c2, self.Pc2g)         # (N,16,16,16) compressed mid-level parts
        c2gw = (c2g * fov2s).reshape(N, 16, -1)                    # foveal-weighted (object-centred)
        c2gw = c2gw - c2gw.mean(dim=2, keepdim=True)
        c2gw = c2gw / (c2gw.norm(dim=2, keepdim=True) + 1e-6)
        gram2 = torch.bmm(c2gw, c2gw.transpose(1, 2))             # (N,16,16) part correlations
        iu3 = torch.triu_indices(16, 16, offset=1, device=gram2.device)
        fc2g = _ln(gram2[:, iu3[0], iu3[1]])                       # 16*15/2 = 120 mid-level part co-occurrence
        return torch.cat([fscat, fraw, gstats, f1, fc, fsgram, fcj, f3, f3max, fc2, fgeom, fc2g, fhue, fhform, ftone, fcscat], dim=1)   # full deep read + compact part-Gram (funded by f1 std grid trim)


MODEL = Model()
